// Types of the Emscripten loader generated by NativeAOT-LLVM (lib/dotasn.js); the exports are in native/Exports.cs.

/** The instantiated WebAssembly module. Pointers and lengths are byte offsets into HEAPU8. */
export interface DotAsnModule {
  readonly HEAPU8: Uint8Array;
  _dotasn_alloc(size: number): number;
  _dotasn_free(pointer: number): void;
  _dotasn_result_ptr(): number;
  _dotasn_result_len(): number;
  _dotasn_load_schema(json: number, length: number): number;
  _dotasn_unload_schema(handle: number): void;
  _dotasn_type_names(handle: number): number;
  _dotasn_encode(handle: number, type: number, typeLength: number, rule: number, ruleLength: number, json: number, jsonLength: number): number;
  _dotasn_decode(handle: number, type: number, typeLength: number, rule: number, ruleLength: number, data: number, dataLength: number, options: number, optionsLength: number): number;
  _dotasn_validate(handle: number, type: number, typeLength: number, json: number, jsonLength: number): number;
}

/** Emscripten module options used by @dotasn/wasm. */
export interface DotAsnModuleOptions {
  locateFile?: (path: string, prefix: string) => string;
  wasmBinary?: ArrayBuffer | Uint8Array;
  instantiateWasm?: (imports: WebAssembly.Imports, success: (instance: WebAssembly.Instance, module: WebAssembly.Module) => void) => unknown;
}

declare function createDotAsnModule(options?: DotAsnModuleOptions): Promise<DotAsnModule>;
export default createDotAsnModule;
